// AAC-LC decoder, written from ISO/IEC 14496-3 (the Huffman and band tables are generated by
// tools/gen_aac_tables.py). See aac.h for what is and is not supported.

#include "aac.h"
#include "aac_tables.h"
#include "msys.h"

#define PI 3.14159265358979323846

#ifdef AAC_COVER
int g_cover[64];                                // feature counters for the host tests (test_aac -DAAC_COVER)
#define COVER(i) (g_cover[i]++)
#else
#define COVER(i) ((void)0)
#endif

// ---------------------------------------------------------------------------------------------
// bit reader

struct bits {
    const uint8_t* p;
    uint32_t pos, nbits;
    int err;
};

static inline uint32_t peek32(const struct bits* b) {
    uint32_t byte = b->pos >> 3, sh = b->pos & 7, nbytes = (b->nbits + 7) >> 3;
    uint64_t w = 0;
    if (byte + 5 <= nbytes) {
        const uint8_t* p = b->p + byte;
        w = ((uint64_t)p[0] << 32) | ((uint64_t)p[1] << 24) | ((uint64_t)p[2] << 16) | ((uint64_t)p[3] << 8) | p[4];
    } else {
        for (int i = 0; i < 5; i++) w = (w << 8) | (byte + (uint32_t)i < nbytes ? b->p[byte + i] : 0);
    }
    return (uint32_t)(w >> (8 - sh));
}

static inline uint32_t get(struct bits* b, int n) {
    if (n <= 0) return 0;
    uint32_t v = peek32(b) >> (32 - n);
    b->pos += (uint32_t)n;
    if (b->pos > b->nbits) b->err = 1;
    return v;
}

static inline void skip(struct bits* b, uint32_t n) {
    b->pos += n;
    if (b->pos > b->nbits) b->err = 1;
}

static inline int get1(struct bits* b) { return (int)get(b, 1); }

static void byte_align(struct bits* b) { b->pos = (b->pos + 7) & ~7u; if (b->pos > b->nbits) b->err = 1; }

// ---------------------------------------------------------------------------------------------
// Huffman lookup built from the generated code lists

#define HB 9                                    // first-level lookup width
#define MAXCODES 300

struct hlut {
    uint16_t first[1 << HB];                    // (index << 5) | length; 0 = longer than HB bits
    int nlong;
    uint32_t lcode[MAXCODES];
    uint8_t llen[MAXCODES];
    uint16_t lidx[MAXCODES];
};

static struct hlut g_hcb[11], g_sf;
static double g_iq[8192];                       // |q|^(4/3)
static double g_pow2q[256];                     // 2^((sf - 100) / 4)
static double g_win_rise[2][2][1024];           // [shape: sine, kbd][long, short] rise half (1024 / 128 entries used)
static int g_init;

static void build_hlut(struct hlut* h, int count, const uint8_t* len, const uint32_t* code32, const uint16_t* code16) {
    for (int i = 0; i < (1 << HB); i++) h->first[i] = 0;
    h->nlong = 0;
    for (int idx = 0; idx < count; idx++) {
        int ln = len[idx];
        uint32_t c = code32 ? code32[idx] : code16[idx];
        if (ln <= HB) {
            uint32_t base = c << (HB - ln);
            for (uint32_t k = 0; k < (1u << (HB - ln)); k++) h->first[base + k] = (uint16_t)((idx << 5) | ln);
        } else {
            // insertion into the long list ordered by length
            int pos = h->nlong++;
            while (pos > 0 && h->llen[pos - 1] > ln) {
                h->lcode[pos] = h->lcode[pos - 1]; h->llen[pos] = h->llen[pos - 1]; h->lidx[pos] = h->lidx[pos - 1];
                pos--;
            }
            h->lcode[pos] = c; h->llen[pos] = (uint8_t)ln; h->lidx[pos] = (uint16_t)idx;
        }
    }
}

static inline int hdecode(struct bits* b, const struct hlut* h) {
    uint32_t v = peek32(b);
    uint16_t e = h->first[v >> (32 - HB)];
    if (e) {
        skip(b, e & 31);
        return e >> 5;
    }
    for (int i = 0; i < h->nlong; i++) {
        int ln = h->llen[i];
        if ((v >> (32 - ln)) == h->lcode[i]) {
            skip(b, (uint32_t)ln);
            return h->lidx[i];
        }
    }
    b->err = 1;
    return -1;
}

// ---------------------------------------------------------------------------------------------
// IMDCT through a DCT-IV computed with a complex FFT of a quarter of the window length

struct mdct {
    int m;                                      // number of coefficients (1024 or 128)
    int l;                                      // FFT size m / 2
    double pre_r[512], pre_i[512];              // exp(-i pi (j + 1/4) / m)
    double post_r[512], post_i[512];            // exp(-i pi j / m)
    double tw_r[256], tw_i[256];                // FFT twiddles exp(-2 pi i k / l)
    uint16_t rev[512];
};

static struct mdct g_mdct_long, g_mdct_short;

static void mdct_init(struct mdct* t, int m) {
    t->m = m;
    t->l = m / 2;
    for (int j = 0; j < t->l; j++) {
        t->pre_r[j] = cos(-PI * (j + 0.25) / m);
        t->pre_i[j] = sin(-PI * (j + 0.25) / m);
        t->post_r[j] = cos(-PI * j / m);
        t->post_i[j] = sin(-PI * j / m);
    }
    for (int k = 0; k < t->l / 2; k++) {
        t->tw_r[k] = cos(-2 * PI * k / t->l);
        t->tw_i[k] = sin(-2 * PI * k / t->l);
    }
    int bits = 0;
    while ((1 << bits) < t->l) bits++;
    for (int i = 0; i < t->l; i++) {
        int r = 0;
        for (int k = 0; k < bits; k++) if (i & (1 << k)) r |= 1 << (bits - 1 - k);
        t->rev[i] = (uint16_t)r;
    }
}

static void fft(const struct mdct* t, double* re, double* im) {
    int n = t->l;
    for (int i = 0; i < n; i++) {
        int j = t->rev[i];
        if (j > i) {
            double a = re[i]; re[i] = re[j]; re[j] = a;
            a = im[i]; im[i] = im[j]; im[j] = a;
        }
    }
    for (int size = 2; size <= n; size <<= 1) {
        int half = size >> 1, step = n / size;
        for (int s = 0; s < n; s += size) {
            for (int k = 0; k < half; k++) {
                double wr = t->tw_r[k * step], wi = t->tw_i[k * step];
                int a = s + k, c = a + half;
                double xr = re[c] * wr - im[c] * wi, xi = re[c] * wi + im[c] * wr;
                re[c] = re[a] - xr; im[c] = im[a] - xi;
                re[a] += xr; im[a] += xi;
            }
        }
    }
}

// x[m] -> out[2m]: out[n] = (1/m) sum_k x[k] cos(pi/m (n + 1/2 + m/2)(k + 1/2))   (the 2/N of the standard, N = 2m).
// u is scratch for m values, tre/tim for m/2 each.
static void imdct(const struct mdct* t, const double* x, double* out, double* u, double* tre, double* tim) {
    int m = t->m, l = t->l, h = m / 2;
    for (int j = 0; j < l; j++) {
        double xr = x[2 * j], xi = x[m - 1 - 2 * j];
        tre[j] = xr * t->pre_r[j] - xi * t->pre_i[j];
        tim[j] = xr * t->pre_i[j] + xi * t->pre_r[j];
    }
    fft(t, tre, tim);
    // DCT-IV: u[2j] = Re(c), u[m-1-2j] = -Im(c) with c = T * post
    for (int j = 0; j < l; j++) {
        double cr = tre[j] * t->post_r[j] - tim[j] * t->post_i[j];
        double ci = tre[j] * t->post_i[j] + tim[j] * t->post_r[j];
        u[2 * j] = cr;
        u[m - 1 - 2 * j] = -ci;
    }
    // unfold the DCT-IV (period 4m, odd symmetry) to 2m samples shifted by m/2
    double scale = 1.0 / m;
    for (int n = 0; n < h; n++) out[n] = u[n + h] * scale;
    for (int n = h; n < 3 * h; n++) out[n] = -u[3 * h - 1 - n] * scale;
    for (int n = 3 * h; n < 2 * m; n++) out[n] = -u[n - 3 * h] * scale;
}

static double bessel_i0(double x) {
    double sum = 1, term = 1, q = x * x / 4;
    for (int k = 1; k < 60; k++) {
        term *= q / ((double)k * k);
        sum += term;
        if (term < sum * 1e-17) break;
    }
    return sum;
}

static void init_tables(void) {
    if (g_init) return;
    g_init = 1;
    for (int i = 0; i < 11; i++)
        build_hlut(&g_hcb[i], aac_hcb[i].count, aac_hcb[i].len, 0, aac_hcb[i].code);
    build_hlut(&g_sf, 121, aac_sf_len, aac_sf_code, 0);
    // |q|^(4/3) = q * cbrt(q); cbrt by exp/log keeps within ~1e-15 relative
    g_iq[0] = 0;
    for (int i = 1; i < 8192; i++) g_iq[i] = exp(log((double)i) * (4.0 / 3.0));
    for (int i = 0; i < 256; i++) g_pow2q[i] = exp(0.69314718055994530942 * (i - 100) / 4.0);
    for (int sh = 0; sh < 2; sh++) {
        for (int sz = 0; sz < 2; sz++) {
            int n = sz ? 128 : 1024;
            double* w = g_win_rise[sh][sz];
            if (sh == 0) {
                for (int i = 0; i < n; i++) w[i] = sin(PI * (i + 0.5) / (2.0 * n));
            } else {
                double alpha = sz ? 6.0 : 4.0;
                double acc = 0, total = 0;
                double kern[1025];
                for (int p = 0; p <= n; p++) {
                    double r = 2.0 * p / n - 1.0;
                    kern[p] = bessel_i0(PI * alpha * sqrt(1.0 - r * r));
                    total += kern[p];
                }
                for (int i = 0; i < n; i++) {
                    acc += kern[i];
                    w[i] = sqrt(acc / total);
                }
            }
        }
    }
    mdct_init(&g_mdct_long, 1024);
    mdct_init(&g_mdct_short, 128);
}

// ---------------------------------------------------------------------------------------------
// decoder state

enum { ONLY_LONG = 0, LONG_START = 1, EIGHT_SHORT = 2, LONG_STOP = 3 };

#define ZERO_HCB 0
#define NOISE_HCB 13
#define INTENSITY_HCB2 14
#define INTENSITY_HCB 15

struct ics {
    int window_sequence, window_shape, max_sfb, grouping;
    int num_windows, num_groups, group_len[8], num_swb;
    const uint16_t* swb;                        // band offsets for this window type
    int global_gain;
    uint8_t sfb_cb[8][64];
    int16_t sf[8][64];
    int ms_mask_present;
    uint8_t ms_used[8][64];
    int pulse_present, pulse_n, pulse_start_sfb, pulse_offset[4], pulse_amp[4];
    int tns_present;
    int tns_n_filt[8], tns_coef_res[8], tns_length[8][4], tns_order[8][4], tns_dir[8][4], tns_compress[8][4];
    uint8_t tns_coef[8][4][32];
};

struct aac_dec {
    int configured;
    int aot, sf_index, sample_rate, channel_config, channels, out_channels;
    int sbr_seen;
    int frame_ch;                               // channels decoded in the current frame
    uint32_t noise_state;
    uint8_t prev_shape[AAC_MAX_CH];
    double overlap[AAC_MAX_CH][AAC_FRAME];
    double pcm[AAC_MAX_CH][AAC_FRAME];
    // scratch
    struct ics ic[2];
    double spec[2][AAC_FRAME];
    int16_t quant[AAC_FRAME];
    double z[2 * AAC_FRAME], y[2 * AAC_FRAME], u[AAC_FRAME], tre[512], tim[512];
};

int aac_adts_parse(const uint8_t* d, size_t len, struct aac_adts* o) {
    if (len < 7 || d[0] != 0xFF || (d[1] & 0xF6) != 0xF0) return -1;   // sync 12 bits, layer 00
    int protection_absent = d[1] & 1;
    o->object_type = ((d[2] >> 6) & 3) + 1;
    o->sf_index = (d[2] >> 2) & 15;
    o->channel_config = ((d[2] & 1) << 2) | (d[3] >> 6);
    o->frame_len = ((d[3] & 3) << 11) | (d[4] << 3) | (d[5] >> 5);
    o->nblocks = (d[6] & 3) + 1;
    o->header_len = protection_absent ? 7 : 9;
    if (o->sf_index >= 12 || o->frame_len < o->header_len) return -1;
    return 0;
}

struct aac_dec* aac_new(void) {
    init_tables();
    struct aac_dec* d = (struct aac_dec*)MEDIA_ALLOC(sizeof(struct aac_dec));
    if (d) aac_reset(d);
    return d;
}

void aac_free(struct aac_dec* d) { MEDIA_FREE(d); }

void aac_reset(struct aac_dec* d) {
    for (int c = 0; c < AAC_MAX_CH; c++) {
        d->prev_shape[c] = 0;
        for (int i = 0; i < AAC_FRAME; i++) d->overlap[c][i] = 0;
    }
    d->noise_state = 0x1f2e3d4c;
}

static const uint8_t k_channels[8] = { 0, 1, 2, 3, 4, 5, 6, 8 };

static void set_channels(struct aac_dec* d, int ch) {
    d->channels = ch;
    d->out_channels = ch >= 2 ? 2 : 1;
}

// program_config_element(): returns the channel count it describes, 0 on error
static int parse_pce(struct bits* b) {
    skip(b, 4 + 2 + 4);                         // tag, profile, sampling index
    int nfront = (int)get(b, 4), nside = (int)get(b, 4), nback = (int)get(b, 4);
    int nlfe = (int)get(b, 2), nassoc = (int)get(b, 3), ncc = (int)get(b, 4);
    if (get1(b)) skip(b, 4);                    // mono mixdown
    if (get1(b)) skip(b, 4);                    // stereo mixdown
    if (get1(b)) skip(b, 3);                    // matrix mixdown + pseudo surround
    int ch = 0;
    for (int i = 0; i < nfront + nside + nback; i++) {
        int cpe = get1(b);
        skip(b, 4);
        ch += cpe ? 2 : 1;
    }
    skip(b, (uint32_t)(nlfe * 4 + nassoc * 4));
    ch += nlfe;
    for (int i = 0; i < ncc; i++) skip(b, 5);
    byte_align(b);
    int comment = (int)get(b, 8);
    skip(b, (uint32_t)comment * 8);
    return b->err ? 0 : ch;
}

int aac_set_config(struct aac_dec* d, const uint8_t* asc, int len) {
    if (!d || !asc || len < 2) return AAC_ERR_BAD_ARG;
    struct bits b = { asc, 0, (uint32_t)len * 8, 0 };
    int aot = (int)get(&b, 5);
    if (aot == 31) aot = 32 + (int)get(&b, 6);
    int sfi = (int)get(&b, 4);
    int rate;
    if (sfi == 15) rate = (int)get(&b, 24);
    else if (sfi < 13) rate = aac_sample_rates[sfi];
    else return AAC_ERR_INVALID;
    int cc = (int)get(&b, 4);
    d->sbr_seen = 0;
    if (aot == 5 || aot == 29) {
        d->sbr_seen = 1;
        int esfi = (int)get(&b, 4);
        if (esfi == 15) skip(&b, 24);
        aot = (int)get(&b, 5);
        if (aot == 31) aot = 32 + (int)get(&b, 6);
    }
    if (b.err) return AAC_ERR_INVALID;
    if (aot != 2) return AAC_ERR_UNSUPPORTED;
    if (get1(&b)) return AAC_ERR_UNSUPPORTED;   // frameLengthFlag: 960
    if (get1(&b)) skip(&b, 14);                 // dependsOnCoreCoder + coreCoderDelay
    if (get1(&b)) skip(&b, 1);                  // extensionFlag (+ flag3)
    int ch = 0;
    if (cc == 0) ch = parse_pce(&b);
    else if (cc < 8) ch = k_channels[cc];
    if (b.err || ch <= 0) return AAC_ERR_INVALID;
    // implicit SBR signalling after the core config: sync 0x2b7, audioObjectType 5, sbrPresentFlag
    if (b.nbits - b.pos >= 16 && peek32(&b) >> 21 == 0x2b7) {
        skip(&b, 11);
        if (get(&b, 5) == 5 && get1(&b)) d->sbr_seen = 1;
    }
    // sample rate -> table index
    int idx = -1;
    for (int i = 0; i < 12; i++) if (aac_sample_rates[i] == rate) idx = i;
    if (idx < 0) return AAC_ERR_UNSUPPORTED;
    d->aot = aot;
    d->sf_index = idx;
    d->sample_rate = rate;
    d->channel_config = cc;
    set_channels(d, ch);
    d->configured = 1;
    aac_reset(d);
    return 0;
}

int aac_set_adts(struct aac_dec* d, const struct aac_adts* h) {
    if (!d || !h) return AAC_ERR_BAD_ARG;
    if (h->object_type != 2) return AAC_ERR_UNSUPPORTED;
    if (h->sf_index >= 12) return AAC_ERR_INVALID;
    int changed = !d->configured || d->sf_index != h->sf_index || d->channel_config != h->channel_config;
    d->aot = 2;
    d->sf_index = h->sf_index;
    d->sample_rate = aac_sample_rates[h->sf_index];
    d->channel_config = h->channel_config;
    if (h->channel_config > 0 && h->channel_config < 8) set_channels(d, k_channels[h->channel_config]);
    else set_channels(d, 2);
    d->configured = 1;
    if (changed) aac_reset(d);
    return 0;
}

void aac_set_output_channels(struct aac_dec* d, int channels) {
    if (channels == 1 || channels == 2) d->out_channels = channels;
}
int aac_channels(const struct aac_dec* d) { return d->channels; }
int aac_out_channels(const struct aac_dec* d) { return d->out_channels; }
int aac_sample_rate(const struct aac_dec* d) { return d->sample_rate; }
int aac_sbr_seen(const struct aac_dec* d) { return d->sbr_seen; }

// ---------------------------------------------------------------------------------------------
// bitstream: individual_channel_stream()

static int read_ics_info(struct aac_dec* d, struct bits* b, struct ics* ic) {
    if (get1(b)) return AAC_ERR_INVALID;        // reserved bit
    ic->window_sequence = (int)get(b, 2);
    ic->window_shape = get1(b);
    if (ic->window_sequence == EIGHT_SHORT) {
        ic->max_sfb = (int)get(b, 4);
        ic->grouping = (int)get(b, 7);
        ic->num_windows = 8;
        ic->num_swb = aac_num_swb_short[d->sf_index];
        ic->swb = aac_swb_short[d->sf_index];
        ic->num_groups = 1;
        ic->group_len[0] = 1;
        for (int i = 0; i < 7; i++) {
            if (!(ic->grouping & (1 << (6 - i)))) ic->group_len[ic->num_groups++] = 1;
            else ic->group_len[ic->num_groups - 1]++;
        }
    } else {
        ic->max_sfb = (int)get(b, 6);
        ic->grouping = 0;
        ic->num_windows = 1;
        ic->num_groups = 1;
        ic->group_len[0] = 1;
        ic->num_swb = aac_num_swb_long[d->sf_index];
        ic->swb = aac_swb_long[d->sf_index];
        if (get1(b)) return AAC_ERR_UNSUPPORTED;   // predictor_data_present (Main prediction / LTP)
    }
    if (b->err) return AAC_ERR_INVALID;
    if (ic->max_sfb > ic->num_swb) return AAC_ERR_INVALID;
    return 0;
}

static int read_section_data(struct bits* b, struct ics* ic) {
    int short_win = ic->window_sequence == EIGHT_SHORT;
    int sect_bits = short_win ? 3 : 5;
    int esc = (1 << sect_bits) - 1;
    for (int g = 0; g < ic->num_groups; g++) {
        int k = 0;
        while (k < ic->max_sfb) {
            int cb = (int)get(b, 4);
            if (cb == 12) return AAC_ERR_INVALID;
            int len = 0, incr = (int)get(b, sect_bits);
            while (incr == esc && !b->err) { len += incr; incr = (int)get(b, sect_bits); }
            len += incr;
            if (b->err || len == 0 || k + len > ic->max_sfb) return AAC_ERR_INVALID;
            for (int s = k; s < k + len; s++) ic->sfb_cb[g][s] = (uint8_t)cb;
            k += len;
        }
    }
    return 0;
}

static int read_scalefactors(struct bits* b, struct ics* ic) {
    int sf = ic->global_gain, is_pos = 0, noise_energy = ic->global_gain - 90, noise_first = 1;
    for (int g = 0; g < ic->num_groups; g++) {
        for (int s = 0; s < ic->max_sfb; s++) {
            int cb = ic->sfb_cb[g][s];
            if (cb == ZERO_HCB) {
                ic->sf[g][s] = 0;
            } else if (cb == INTENSITY_HCB || cb == INTENSITY_HCB2) {
                int t = hdecode(b, &g_sf);
                if (t < 0) return AAC_ERR_INVALID;
                is_pos += t - 60;
                ic->sf[g][s] = (int16_t)is_pos;
            } else if (cb == NOISE_HCB) {
                if (noise_first) {
                    noise_first = 0;
                    noise_energy += (int)get(b, 9) - 256;
                } else {
                    int t = hdecode(b, &g_sf);
                    if (t < 0) return AAC_ERR_INVALID;
                    noise_energy += t - 60;
                }
                ic->sf[g][s] = (int16_t)noise_energy;
            } else {
                int t = hdecode(b, &g_sf);
                if (t < 0) return AAC_ERR_INVALID;
                sf += t - 60;
                if (sf < 0 || sf > 255) return AAC_ERR_INVALID;
                ic->sf[g][s] = (int16_t)sf;
            }
            if (b->err) return AAC_ERR_INVALID;
        }
    }
    return 0;
}

static int read_pulse(struct bits* b, struct ics* ic) {
    ic->pulse_n = (int)get(b, 2);
    ic->pulse_start_sfb = (int)get(b, 6);
    if (ic->pulse_start_sfb > ic->num_swb) return AAC_ERR_INVALID;
    for (int i = 0; i <= ic->pulse_n; i++) {
        ic->pulse_offset[i] = (int)get(b, 5);
        ic->pulse_amp[i] = (int)get(b, 4);
    }
    return b->err ? AAC_ERR_INVALID : 0;
}

static void read_tns(struct bits* b, struct ics* ic) {
    int short_win = ic->window_sequence == EIGHT_SHORT;
    int n_filt_bits = short_win ? 1 : 2, length_bits = short_win ? 4 : 6, order_bits = short_win ? 3 : 5;
    for (int w = 0; w < ic->num_windows; w++) {
        int start_bits = 3;
        ic->tns_n_filt[w] = (int)get(b, n_filt_bits);
        if (ic->tns_n_filt[w]) {
            ic->tns_coef_res[w] = get1(b);
            if (ic->tns_coef_res[w]) start_bits = 4;
        }
        for (int f = 0; f < ic->tns_n_filt[w]; f++) {
            ic->tns_length[w][f] = (int)get(b, length_bits);
            ic->tns_order[w][f] = (int)get(b, order_bits);
            ic->tns_dir[w][f] = 0;
            ic->tns_compress[w][f] = 0;
            if (ic->tns_order[w][f]) {
                ic->tns_dir[w][f] = get1(b);
                ic->tns_compress[w][f] = get1(b);
                int nb = start_bits - ic->tns_compress[w][f];
                for (int i = 0; i < ic->tns_order[w][f]; i++) ic->tns_coef[w][f][i] = (uint8_t)get(b, nb);
            }
        }
    }
}

// escape sequence of codebook 11 (a magnitude of 16 means "more follows")
static int read_escape(struct bits* b) {
    int n = 4;
    while (get1(b)) {
        n++;
        COVER(7);
        if (n > 15 || b->err) { b->err = 1; return 0; }
    }
    return (int)get(b, n) + (1 << n);
}

// spectral_data(): the quantized values land at their final frequency positions (window-major for short blocks)
static int read_spectral(struct aac_dec* d, struct bits* b, const struct ics* ic) {
    int16_t* q = d->quant;
    for (int i = 0; i < AAC_FRAME; i++) q[i] = 0;
    int short_win = ic->window_sequence == EIGHT_SHORT;
    int win0 = 0;
    for (int g = 0; g < ic->num_groups; g++) {
        for (int s = 0; s < ic->max_sfb; s++) {
            int cb = ic->sfb_cb[g][s];
            if (cb == ZERO_HCB || cb >= NOISE_HCB) continue;
            const struct aac_hcb* cbk = &aac_hcb[cb - 1];
            const struct hlut* lut = &g_hcb[cb - 1];
            int nv = cbk->nvals, mod = cbk->mod, off = cbk->off;
            int unsigned_book = (cb == 3 || cb == 4 || cb >= 7);
            int width = ic->swb[s + 1] - ic->swb[s];
            for (int w = 0; w < ic->group_len[g]; w++) {
                int pos = (short_win ? (win0 + w) * 128 : 0) + ic->swb[s];
                for (int k = 0; k < width; k += nv) {
                    int idx = hdecode(b, lut);
                    if (idx < 0 || b->err) return AAC_ERR_INVALID;
                    int val[4];
                    for (int i = nv - 1; i >= 0; i--) { val[i] = idx % mod - off; idx /= mod; }
                    if (unsigned_book) {
                        int neg[4];
                        for (int i = 0; i < nv; i++) neg[i] = val[i] ? get1(b) : 0;
                        if (cb == 11) {
                            for (int i = 0; i < nv; i++) if (val[i] == 16) val[i] = read_escape(b);
                        }
                        for (int i = 0; i < nv; i++) if (neg[i]) val[i] = -val[i];
                    }
                    for (int i = 0; i < nv; i++) {
                        if (val[i] > 8191 || val[i] < -8191) return AAC_ERR_INVALID;
                        q[pos + k + i] = (int16_t)val[i];
                    }
                }
            }
        }
        win0 += ic->group_len[g];
    }
    return b->err ? AAC_ERR_INVALID : 0;
}

static int apply_pulse(struct aac_dec* d, const struct ics* ic) {
    int k = ic->swb[ic->pulse_start_sfb];
    for (int i = 0; i <= ic->pulse_n; i++) {
        k += ic->pulse_offset[i];
        if (k >= AAC_FRAME) return AAC_ERR_INVALID;
        int v = d->quant[k];
        v += v > 0 ? ic->pulse_amp[i] : -ic->pulse_amp[i];
        if (v > 8191 || v < -8191) return AAC_ERR_INVALID;
        d->quant[k] = (int16_t)v;
    }
    return 0;
}

// individual_channel_stream() up to (and including) the dequantized spectrum
static int read_channel(struct aac_dec* d, struct bits* b, struct ics* ic, int common_window, double* spec) {
    int r;
    ic->global_gain = (int)get(b, 8);
    if (!common_window) {
        if ((r = read_ics_info(d, b, ic)) < 0) return r;
    }
    if ((r = read_section_data(b, ic)) < 0) return r;
    if ((r = read_scalefactors(b, ic)) < 0) return r;
    ic->pulse_present = get1(b);
    if (ic->pulse_present) {
        if ((r = read_pulse(b, ic)) < 0) return r;
        if (ic->window_sequence == EIGHT_SHORT) return AAC_ERR_INVALID;
    }
    ic->tns_present = get1(b);
    if (ic->tns_present) read_tns(b, ic);
    if (get1(b)) return AAC_ERR_UNSUPPORTED;    // gain control (SSR)
    if (b->err) return AAC_ERR_INVALID;
    if ((r = read_spectral(d, b, ic)) < 0) return r;
    COVER(ic->window_sequence);
    if (ic->num_groups > 1) COVER(4);
    if (ic->tns_present) COVER(5);
    if (ic->pulse_present) COVER(6);
    for (int g = 0; g < ic->num_groups; g++)
        for (int s = 0; s < ic->max_sfb; s++) COVER(16 + ic->sfb_cb[g][s]);
    if (ic->pulse_present && (r = apply_pulse(d, ic)) < 0) return r;

    // dequantize: sign(q) |q|^(4/3) 2^((sf - 100) / 4)
    int short_win = ic->window_sequence == EIGHT_SHORT;
    for (int i = 0; i < AAC_FRAME; i++) spec[i] = 0;
    int win0 = 0;
    for (int g = 0; g < ic->num_groups; g++) {
        for (int s = 0; s < ic->max_sfb; s++) {
            int cb = ic->sfb_cb[g][s];
            if (cb == ZERO_HCB || cb >= NOISE_HCB) continue;
            double scf = g_pow2q[ic->sf[g][s]];
            for (int w = 0; w < ic->group_len[g]; w++) {
                int base = short_win ? (win0 + w) * 128 : 0;
                for (int k = ic->swb[s]; k < ic->swb[s + 1]; k++) {
                    int v = d->quant[base + k];
                    spec[base + k] = (v < 0 ? -g_iq[-v] : g_iq[v]) * scf;
                }
            }
        }
        win0 += ic->group_len[g];
    }
    return 0;
}

// ---------------------------------------------------------------------------------------------
// reconstruction tools

static void fill_noise(struct aac_dec* d, double* spec, int size, int sf, uint32_t* state) {
    if (size <= 0) return;
    if (sf > 120) sf = 120;
    if (sf < -120) sf = -120;
    double energy = 0;
    uint32_t st = *state;
    for (int i = 0; i < size; i++) {
        st = st * 1664525u + 1013904223u;
        double v = (double)(int32_t)st;
        spec[i] = v;
        energy += v * v;
    }
    *state = st;
    (void)d;
    if (energy > 0) {
        double scale = exp(0.69314718055994530942 * 0.25 * sf) / sqrt(energy);
        for (int i = 0; i < size; i++) spec[i] *= scale;
    }
}

static void pns(struct aac_dec* d, const struct ics* l, const struct ics* r, double* sl, double* sr) {
    int short_win = l->window_sequence == EIGHT_SHORT;
    int win0 = 0;
    for (int g = 0; g < l->num_groups; g++) {
        for (int w = 0; w < l->group_len[g]; w++) {
            int base = short_win ? (win0 + w) * 128 : 0;
            for (int s = 0; s < l->max_sfb; s++) {
                uint32_t dep = d->noise_state;
                int a = base + l->swb[s], n = l->swb[s + 1] - l->swb[s];
                int lnoise = l->sfb_cb[g][s] == NOISE_HCB;
                if (lnoise) fill_noise(d, sl + a, n, l->sf[g][s], &d->noise_state);
                if (r && r->sfb_cb[g][s] == NOISE_HCB) {
                    int shared = lnoise && ((l->ms_mask_present == 1 && l->ms_used[g][s]) || l->ms_mask_present == 2);
                    if (shared) fill_noise(d, sr + a, n, r->sf[g][s], &dep);
                    else fill_noise(d, sr + a, n, r->sf[g][s], &d->noise_state);
                }
            }
        }
        win0 += l->group_len[g];
    }
}

static void ms_stereo(const struct ics* l, const struct ics* r, double* sl, double* sr) {
    if (l->ms_mask_present == 0) return;
    int short_win = l->window_sequence == EIGHT_SHORT;
    int win0 = 0;
    for (int g = 0; g < l->num_groups; g++) {
        for (int w = 0; w < l->group_len[g]; w++) {
            int base = short_win ? (win0 + w) * 128 : 0;
            for (int s = 0; s < l->max_sfb; s++) {
                if (!(l->ms_used[g][s] || l->ms_mask_present == 2)) continue;
                if (l->sfb_cb[g][s] >= NOISE_HCB || r->sfb_cb[g][s] >= NOISE_HCB) continue;
                for (int k = base + l->swb[s]; k < base + l->swb[s + 1]; k++) {
                    double a = sl[k], c = sr[k];
                    sl[k] = a + c;
                    sr[k] = a - c;
                }
            }
        }
        win0 += l->group_len[g];
    }
}

static void intensity_stereo(const struct ics* l, const struct ics* r, double* sl, double* sr) {
    int short_win = r->window_sequence == EIGHT_SHORT;
    int win0 = 0;
    for (int g = 0; g < r->num_groups; g++) {
        for (int w = 0; w < r->group_len[g]; w++) {
            int base = short_win ? (win0 + w) * 128 : 0;
            for (int s = 0; s < r->max_sfb; s++) {
                int cb = r->sfb_cb[g][s];
                if (cb != INTENSITY_HCB && cb != INTENSITY_HCB2) continue;
                int pos = r->sf[g][s];
                if (pos > 120) pos = 120;
                if (pos < -120) pos = -120;
                double scale = exp(-0.69314718055994530942 * 0.25 * pos);
                int neg = (cb == INTENSITY_HCB2);
                // ms_mask_present == 2 means ms_used is 1 everywhere, which also flips the intensity sign
                if ((l->ms_mask_present == 1 && l->ms_used[g][s]) || l->ms_mask_present == 2) neg = !neg;
                if (neg) scale = -scale;
                for (int k = base + r->swb[s]; k < base + r->swb[s + 1]; k++) sr[k] = sl[k] * scale;
            }
        }
        win0 += r->group_len[g];
    }
}

static void tns_filter(const struct aac_dec* d, const struct ics* ic, double* spec) {
    if (!ic->tns_present) return;
    int short_win = ic->window_sequence == EIGHT_SHORT;
    int maxb = short_win ? aac_tns_max_short[d->sf_index] : aac_tns_max_long[d->sf_index];
    for (int w = 0; w < ic->num_windows; w++) {
        int bottom = ic->num_swb;
        for (int f = 0; f < ic->tns_n_filt[w]; f++) {
            int top = bottom;
            bottom = top - ic->tns_length[w][f];
            if (bottom < 0) bottom = 0;
            int order = ic->tns_order[w][f];
            if (order > 20) order = 20;
            if (!order) continue;
            // reflection coefficients -> LPC
            int res_bits = 3 + ic->tns_coef_res[w], nb = res_bits - ic->tns_compress[w][f];
            double refl[20], a[21], tmp[21];
            for (int i = 0; i < order; i++) {
                int c = ic->tns_coef[w][f][i];
                int sv = c >= (1 << (nb - 1)) ? c - (1 << nb) : c;
                double iqfac = (((1 << (res_bits - 1)) + (sv >= 0 ? -0.5 : 0.5))) / (PI / 2);
                refl[i] = sin(sv / iqfac);
            }
            a[0] = 1;
            for (int m = 1; m <= order; m++) {
                a[m] = refl[m - 1];
                for (int i = 1; i < m; i++) tmp[i] = a[i] + a[m] * a[m - i];
                for (int i = 1; i < m; i++) a[i] = tmp[i];
            }
            int start = bottom < maxb ? bottom : maxb;
            if (start > ic->max_sfb) start = ic->max_sfb;
            start = ic->swb[start];
            int end = top < maxb ? top : maxb;
            if (end > ic->max_sfb) end = ic->max_sfb;
            end = ic->swb[end];
            int size = end - start;
            if (size <= 0) continue;
            double* x = spec + (short_win ? w * 128 : 0);
            int inc = 1;
            if (ic->tns_dir[w][f]) { inc = -1; start = end - 1; }
            double hist[20] = { 0 };            // hist[0] = most recent output
            for (int i = 0; i < size; i++) {
                double y = x[start + i * inc];
                for (int j = 0; j < order; j++) y -= a[j + 1] * hist[j];
                for (int j = order - 1; j > 0; j--) hist[j] = hist[j - 1];
                hist[0] = y;
                x[start + i * inc] = y;
            }
        }
    }
}

// windowing + overlap-add; spec (1024 coefficients) -> pcm[ch][1024]
static void filterbank(struct aac_dec* d, int ch, const struct ics* ic, const double* spec) {
    double* z = d->z;
    double* y = d->y;
    int ps = d->prev_shape[ch], cs = ic->window_shape;
    const double* lw_prev = g_win_rise[ps][0];
    const double* lw = g_win_rise[cs][0];
    const double* sw = g_win_rise[cs][1];
    const double* sw_prev = g_win_rise[ps][1];
    switch (ic->window_sequence) {
    case ONLY_LONG:
        imdct(&g_mdct_long, spec, y, d->u, d->tre, d->tim);
        for (int n = 0; n < 1024; n++) z[n] = y[n] * lw_prev[n];
        for (int n = 0; n < 1024; n++) z[1024 + n] = y[1024 + n] * lw[1023 - n];
        break;
    case LONG_START:
        imdct(&g_mdct_long, spec, y, d->u, d->tre, d->tim);
        for (int n = 0; n < 1024; n++) z[n] = y[n] * lw_prev[n];
        for (int n = 0; n < 448; n++) z[1024 + n] = y[1024 + n];
        for (int n = 0; n < 128; n++) z[1472 + n] = y[1472 + n] * sw[127 - n];
        for (int n = 0; n < 448; n++) z[1600 + n] = 0;
        break;
    case LONG_STOP:
        imdct(&g_mdct_long, spec, y, d->u, d->tre, d->tim);
        for (int n = 0; n < 448; n++) z[n] = 0;
        for (int n = 0; n < 128; n++) z[448 + n] = y[448 + n] * sw_prev[n];
        for (int n = 0; n < 448; n++) z[576 + n] = y[576 + n];
        for (int n = 0; n < 1024; n++) z[1024 + n] = y[1024 + n] * lw[1023 - n];
        break;
    default:                                    // EIGHT_SHORT
        for (int n = 0; n < 2048; n++) z[n] = 0;
        for (int k = 0; k < 8; k++) {
            imdct(&g_mdct_short, spec + k * 128, y, d->u, d->tre, d->tim);
            const double* rise = k == 0 ? sw_prev : sw;
            double* o = z + 448 + 128 * k;
            for (int n = 0; n < 128; n++) o[n] += y[n] * rise[n];
            for (int n = 0; n < 128; n++) o[128 + n] += y[128 + n] * sw[127 - n];
        }
        break;
    }
    double* out = d->pcm[ch];
    double* ov = d->overlap[ch];
    for (int n = 0; n < 1024; n++) {
        out[n] = ov[n] + z[n];
        ov[n] = z[1024 + n];
    }
    d->prev_shape[ch] = (uint8_t)cs;
}

// ---------------------------------------------------------------------------------------------
// elements

static int decode_sce(struct aac_dec* d, struct bits* b) {
    if (d->frame_ch >= AAC_MAX_CH) return AAC_ERR_UNSUPPORTED;
    skip(b, 4);                                 // element_instance_tag
    struct ics* ic = &d->ic[0];
    memset(ic, 0, sizeof *ic);
    int r = read_channel(d, b, ic, 0, d->spec[0]);
    if (r < 0) return r;
    for (int g = 0; g < ic->num_groups; g++)
        for (int s = 0; s < ic->max_sfb; s++)
            if (ic->sfb_cb[g][s] == INTENSITY_HCB || ic->sfb_cb[g][s] == INTENSITY_HCB2) return AAC_ERR_INVALID;
    pns(d, ic, 0, d->spec[0], 0);
    tns_filter(d, ic, d->spec[0]);
    filterbank(d, d->frame_ch++, ic, d->spec[0]);
    return 0;
}

static int decode_cpe(struct aac_dec* d, struct bits* b) {
    if (d->frame_ch + 2 > AAC_MAX_CH) return AAC_ERR_UNSUPPORTED;
    skip(b, 4);
    struct ics* l = &d->ic[0];
    struct ics* r = &d->ic[1];
    memset(l, 0, sizeof *l);
    memset(r, 0, sizeof *r);
    int common = get1(b), rc;
    if (common) {
        if ((rc = read_ics_info(d, b, l)) < 0) return rc;
        l->ms_mask_present = (int)get(b, 2);
        if (l->ms_mask_present == 3) return AAC_ERR_INVALID;
        if (l->ms_mask_present == 1) {
            for (int g = 0; g < l->num_groups; g++)
                for (int s = 0; s < l->max_sfb; s++) l->ms_used[g][s] = (uint8_t)get1(b);
        }
        // the second channel shares the window information
        r->window_sequence = l->window_sequence; r->window_shape = l->window_shape;
        r->max_sfb = l->max_sfb; r->grouping = l->grouping; r->num_windows = l->num_windows;
        r->num_groups = l->num_groups; r->num_swb = l->num_swb; r->swb = l->swb;
        for (int g = 0; g < 8; g++) r->group_len[g] = l->group_len[g];
    }
    if ((rc = read_channel(d, b, l, common, d->spec[0])) < 0) return rc;
    if ((rc = read_channel(d, b, r, common, d->spec[1])) < 0) return rc;
    COVER(8 + l->ms_mask_present);
    pns(d, l, r, d->spec[0], d->spec[1]);
    ms_stereo(l, r, d->spec[0], d->spec[1]);
    intensity_stereo(l, r, d->spec[0], d->spec[1]);
    tns_filter(d, l, d->spec[0]);
    tns_filter(d, r, d->spec[1]);
    filterbank(d, d->frame_ch++, l, d->spec[0]);
    filterbank(d, d->frame_ch++, r, d->spec[1]);
    return 0;
}

static void skip_dse(struct bits* b) {
    int align = get1(b);
    int cnt = (int)get(b, 8);
    if (cnt == 255) cnt += (int)get(b, 8);
    if (align) byte_align(b);
    skip(b, (uint32_t)cnt * 8);
}

static void skip_fill(struct aac_dec* d, struct bits* b) {
    int cnt = (int)get(b, 4);
    if (cnt == 15) cnt += (int)get(b, 8) - 1;
    if (cnt > 0 && !b->err) {
        uint32_t t = peek32(b) >> 28;           // extension_type
        if (t == 13 || t == 14) d->sbr_seen = 1;
    }
    skip(b, (uint32_t)cnt * 8);
}

// ---------------------------------------------------------------------------------------------
// output

static inline int16_t to_s16(double v) {
    if (v >= 32767.0) return 32767;
    if (v <= -32768.0) return -32768;
    return (int16_t)(v >= 0 ? (int)(v + 0.5) : -(int)(0.5 - v));
}

static void emit(struct aac_dec* d, int16_t* pcm) {
    int n = d->frame_ch, oc = d->out_channels;
    if (n == 0) {
        for (int i = 0; i < AAC_FRAME * oc; i++) pcm[i] = 0;
        return;
    }
    for (int i = 0; i < AAC_FRAME; i++) {
        double l, r;
        if (n == 1) {
            l = r = d->pcm[0][i];
        } else if (n == 2) {
            l = d->pcm[0][i];
            r = d->pcm[1][i];
        } else {
            // stream order: C, L, R, (Ls, Rs | S), ... ; mix down with the usual 0.707 centre/surround weights
            const double k = 0.70710678118654752;
            double c = d->pcm[0][i];
            l = d->pcm[1][i] + k * c;
            r = d->pcm[2][i] + k * c;
            double norm = 1.0 + k;
            if (n >= 4) {
                if (n == 4) { l += k * d->pcm[3][i]; r += k * d->pcm[3][i]; }
                else { l += k * d->pcm[3][i]; r += k * d->pcm[4][i]; }
                norm += k;
            }
            if (n >= 7) { l += 0.5 * d->pcm[5][i]; r += 0.5 * d->pcm[6][i]; norm += 0.5; }
            l /= norm;
            r /= norm;
        }
        if (oc == 2) {
            pcm[2 * i] = to_s16(l);
            pcm[2 * i + 1] = to_s16(r);
        } else {
            pcm[i] = to_s16(n == 1 ? l : 0.5 * (l + r));
        }
    }
}

int aac_decode(struct aac_dec* d, const uint8_t* data, size_t len, int16_t* pcm) {
    if (!d || !pcm || !d->configured) return AAC_ERR_BAD_ARG;
    if (!data || len == 0) {                    // lost frame: silence, forget the overlap
        for (int i = 0; i < AAC_FRAME * d->out_channels; i++) pcm[i] = 0;
        aac_reset(d);
        return AAC_FRAME;
    }
    struct bits b = { data, 0, (uint32_t)len * 8, 0 };
    d->frame_ch = 0;
    int r = 0;
    for (;;) {
        int id = (int)get(&b, 3);
        if (b.err) { r = AAC_ERR_INVALID; break; }
        if (id == 7) break;                     // ID_END
        switch (id) {
        case 0: case 3: r = decode_sce(d, &b); break;
        case 1: r = decode_cpe(d, &b); break;
        case 2: r = AAC_ERR_UNSUPPORTED; break; // coupling channel
        case 4: skip_dse(&b); break;
        case 5: if (!parse_pce(&b)) r = AAC_ERR_INVALID; break;   // in-stream PCEs are ignored
        case 6: skip_fill(d, &b); break;
        }
        if (r < 0 || b.err) { if (r >= 0) r = AAC_ERR_INVALID; break; }
    }
    if (r < 0) return r;
    emit(d, pcm);
    return AAC_FRAME;
}
